calls.expression:
canonical({
          packageId: node.provider.packageId,
          packageVersion: node.provider.packageVersion,
          contentDigest: node.provider.contentDigest,
        })

canonicalJson(candidates.map(({ path, digest, reasons, dependencyDepth }) => ({
    path, digest, reasons, dependencyDepth,
  })))

canonicalJson({
      version: REVIEW_CLUSTER_SCHEMA_VERSION,
      repositoryBase,
      singletonFinding: finding.fingerprint,
    })

canonicalJson({
    uncoveredFiles: plan.coverage.uncoveredFiles.slice(0, 10),
    unresolvedRelations: graph.unresolvedRelations.slice(0, 10), overflows: plan.coverage.overflows.slice(0, 10),
  })

canonicalJson({
    category: finding.category, priority: finding.priority, claim: finding.claim,
    locations: finding.locations, recommendedFix: finding.recommendedFix,
  })

canonicalJson({
    category: job.proposal.finding.category, rootCauseHint: job.proposal.finding.rootCauseHint,
    primaryPath: job.proposal.finding.locations[0]?.path,
  })

canonical({
    type: event.type, identity: event.identity, payload: event.payload,
  })
